//! The write guard of Blog (generated by metaphor-schema; do not edit). It lives in a
//! file of its own because `blog_service.rs` is hand-owned.

#[allow(unused_imports)]
use super::*;
use crate::domain::entity::Blog;

/// The rules the schema declares for Blog, checked against the row a create or update
/// would store. The generated build attaches it to [`BlogService`]. A refusing rule's
/// break answers 422; a rule in shadow is logged under `backbone::write_guard` and the
/// write goes ahead.
pub struct BlogRowRules;

#[async_trait::async_trait]
impl backbone_core::write_guard::WriteGuard<Blog> for BlogRowRules {
    async fn check(
        &self,
        ctx: &backbone_core::write_guard::WriteCtx<'_, Blog>,
    ) -> backbone_core::write_guard::GuardOutcome {
        use backbone_core::row_rule as r;
        use backbone_core::violation::Violation;
        use backbone_core::write_guard::{GuardOutcome, WriteKind};
        let (create, update) = (ctx.kind == WriteKind::Create, ctx.kind == WriteKind::Update);
        let Some(after) = ctx.after.filter(|_| create || update) else {
            return GuardOutcome::allow();
        };
        let Ok(row) = serde_json::to_value(after) else {
            return GuardOutcome::allow();
        };
        let row = &row;
        let old = ctx.before.and_then(|b| serde_json::to_value(b).ok());
        let mut shadow = Vec::new();
        let mut refuse = Vec::new();
        // `website_id_required` (@required on Blog.website_id)
        if (create || (update && r::changed(old.as_ref(), row, &["website_id"]))) && !r::holds(&r::and(r::is_not_null(r::field(row, "website_id")), r::not(r::is_empty(r::trim(r::field(row, "website_id")))))) {
            refuse.push(Violation::new("website_id", "required", "website_id is required"));
        }
        // `name_required` (@required on Blog.name)
        if (create || (update && r::changed(old.as_ref(), row, &["name"]))) && !r::holds(&r::and(r::is_not_null(r::field(row, "name")), r::not(r::is_empty(r::trim(r::field(row, "name")))))) {
            refuse.push(Violation::new("name", "required", "name is required"));
        }
        // `name_max_length` (@max(120) on Blog.name)
        if (create || (update && r::changed(old.as_ref(), row, &["name"]))) && !r::holds(&r::le(r::length(r::field(row, "name")), r::Val::Num(120.0_f64))) {
            shadow.push(Violation::new("name", "max_length", "name must be at most 120 characters").with_param("max", 120_i64));
        }
        // `subtitle_max_length` (@max(500) on Blog.subtitle)
        if (create || (update && r::changed(old.as_ref(), row, &["subtitle"]))) && !r::holds(&r::le(r::length(r::field(row, "subtitle")), r::Val::Num(500.0_f64))) {
            shadow.push(Violation::new("subtitle", "max_length", "subtitle must be at most 500 characters").with_param("max", 500_i64));
        }
        GuardOutcome { refuse, shadow }
    }
}
